code.cpp:
class Solution {
public:
    int longestPalindrome(string s) {
        int freq[128] = {0};
        for (char c : s) {
            freq[c]++;
        }
        int length = 0;
        bool hasOdd = false;
        for (int i = 0; i < 128; i++) {
            length += (freq[i] / 2) * 2;
            if (freq[i] % 2 == 1) hasOdd = true;
        }
        return length + (hasOdd ? 1 : 0);
    }
};
